{{ config(materialized = 'ephemeral') }}

-- ZOOMINFO_DEV -> company_industry: generated by dbt-onboard-source from the approved STTM.
-- SOURCE_UNIQUE_ID: STTM business keys.

with sp_company_industry as (
    select
        upper(trim(o.ZOOMINFO_ID)) as source_unique_id,
        o.GDP_IS_ACTIVE as is_primary_industry,
        o.GDP_INSERTED_TS,
        o.GDP_UPDATED_TS
    from {{ source('company_industry_zoominfo_dev_source', 'silver_zoominfo_company') }} as o
    where nullif(upper(trim(o.ZOOMINFO_ID)), '') is not null
    qualify row_number() over (partition by upper(trim(o.ZOOMINFO_ID)) order by o.GDP_UPDATED_TS desc) = 1
),

ref_source_system as (
    {{ m_get_source_system_skey_company('ZOOMINFO_DEV') }}
),

base as (
    select
        o.source_unique_id,
        r.gdp_source_system_skey as ref_gdp_source_system_skey,
        hub.company_core_skey as company_core_skey,
        null as ref_industry_name_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for REF_INDUSTRY_NAME_SKEY */,
        null as source_naics_code,
        null as source_naics_description,
        o.is_primary_industry as is_primary_industry,
        o.GDP_IS_ACTIVE as gdp_is_active,
        o.GDP_INSERTED_TS as gdp_inserted_ts,
        current_user() as gdp_inserted_by,
        o.GDP_UPDATED_TS as gdp_updated_ts,
        current_user() as gdp_updated_by
    from sp_company_industry as o
    cross join ref_source_system as r
    left join (
        select source_unique_id, company_core_skey
        from {{ ref('company_core') }}
        where gdp_is_active
        qualify row_number() over (partition by source_unique_id order by gdp_inserted_ts desc) = 1
    ) as hub
        on hub.source_unique_id = o.source_unique_id
)

select
    {{ this.schema }}.seq_company_industry_skey.nextval as company_industry_skey,
    source_unique_id,
    ref_gdp_source_system_skey,
    company_core_skey,
    ref_industry_name_skey,
    source_naics_code,
    source_naics_description,
    is_primary_industry,
    {{ m_company_industry_hkey() }} as company_industry_hkey,
    gdp_is_active,
    gdp_inserted_ts,
    gdp_inserted_by,
    gdp_updated_ts,
    gdp_updated_by
from base
